def clean(df):
    df['Quantity'] = pd.to_numeric(df['Quantity'], errors='coerce')
    df['Region'] = df['Region'].str.strip().str.lower()
    df['Region'] = df['Region'].replace({'west': 'west', 'south': 'south', 'wst': 'west', 'suoth': 'south'})
    df['Region'] = df['Region'].str.title()
    df = df.dropna(subset=['Region'])
    df = df[df['Quantity'] >= 1]
    return df

def answer(df):
    return df.groupby('Region')['Quantity'].sum().to_dict()
